
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_gea2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_gea2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.386841522716845e+02, -2.001372467907952e+02, -1.063120093759304e+02, -4.435286820485963e+01, -5.387347364366495e+00, 1.685009197268021e+01, 2.709968351142422e+01, 2.940734096529165e+01, 2.754428140925304e+01, 2.445278009270683e+01, 1.873335548493083e+01, 5.842593045420461e+00, 1.325183410364228e+00, 1.225659279487304e+00, 1.105662643489665e+00, 9.296010448703680e-01, 8.330429365822607e-01, 7.901147291166705e-01, 7.696551572394421e-01, 7.603885974794720e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


